function renderManagerJourney(){
 if(view!=='club')return;
 const host=$('manager-journey');if(!host)return;
 const model=ManagerJourney.read(season),s=model.season,esc=escapeText;
 const expanded=host.querySelector('details')?.open||false;
 host.innerHTML=`<section class="manager-journey-card" aria-labelledby="manager-journey-title"><div class="journey-heading"><div><span class="eyebrow">YOUR MANAGER STORY</span><h2 id="manager-journey-title">우승까지의 여정</h2></div><span class="journey-count">${model.completed} / ${model.total} 달성</span></div><p class="journey-next"><strong>${model.next?'다음 도전 · '+esc(model.next.title):'모든 이정표 달성 · 이제 왕조를 이어가세요'}</strong><span>${model.next?esc(model.next.hint):'다음 시즌에도 새로운 선수와 함께 우승에 도전할 수 있습니다.'}</span></p><div class="journey-season"><span>${s.year}시즌 · ${s.division}부 · ${s.rank?s.rank+'위 · '+s.points+'점':'첫 경기 준비'}</span><span>${s.final?'리그 종료':'리그 '+s.remaining+'경기 남음'}</span></div><progress max="14" value="${s.played}" aria-label="확정된 리그 경기 ${s.played} / 14"></progress><details${expanded?' open':''}><summary>나의 이정표와 다음 시즌</summary><ol class="journey-milestones">${model.milestones.map(m=>`<li class="${m.achieved?'achieved':''}"><span class="journey-marker" aria-hidden="true">${m.achieved?'✓':'○'}</span><div><strong>${esc(m.title)}</strong><small>${m.achieved?'달성 · '+esc(m.evidence):esc(m.hint)}</small></div></li>`).join('')}</ol><p class="journey-carry">${esc(model.carry)}</p>${model.partial?'<p class="journey-carry">이전 저장에 없는 승리 기록은 추정하지 않습니다. 남아 있는 확정 기록부터 표시합니다.</p>':''}<p class="journey-carry">목표는 각각 달성할 수 있으며, 이정표 자체로 추가 자금이나 능력치를 지급하지 않습니다.</p></details><div class="journey-actions"><button type="button" id="journey-continue" class="secondary">${{season:'다음 시즌 준비',result:'경기 결과 확정하러 가기',match:'다음 경기 준비'}[model.action]}</button><button type="button" id="journey-competitions" class="text-button">대회 기록 보기 →</button></div></section>`;
 $('journey-continue').onclick=()=>{if(model.action==='season'){setMobileDashboardExpanded(true);$('next-season')?.scrollIntoView({block:'center',behavior:'instant'});$('next-season')?.focus({preventScroll:true});}else setView('match');};
 $('journey-competitions').onclick=()=>setView('cup');
}
